(()=>{
 const ns='http://www.w3.org/2000/svg',out={},make=(tag,attrs={},text='')=>{const n=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));n.textContent=text;return n},svg=make('svg',{width:600,height:300});document.body.appendChild(svg);
 const box=n=>{const b=n.getBBox();return [b.x,b.y,b.width,b.height]},run=(name,fn)=>{try{out[name]=fn()}catch(e){out[name]={error:e.name}}};
 for(const [name,attrs,text] of [['default',{},'AAAA'],['changed',{},'AAAB'],['empty',{},''],['spaces',{},'   '],['trim',{},'  A  B  '],['times',{'font-family':'Times New Roman','font-size':16},'AVfi gj'],['arial',{'font-family':'Arial','font-size':16},'AVfi gj'],['courier',{'font-family':'Courier New','font-size':16},'AVfi gj'],['mono',{'font-family':'monospace','font-size':16},'ABCD'],['sans',{'font-family':'sans-serif','font-size':16},'ABCD'],['small',{'font-family':'Arial','font-size':10},'Hello'],['large',{'font-family':'Arial','font-size':32},'Hello'],['fractional',{'font-family':'Arial','font-size':13.5},'Hello'],['bold',{'font-family':'Arial','font-size':16,'font-weight':'bold'},'Hello'],['italic',{'font-family':'Arial','font-size':16,'font-style':'italic'},'fij'],['position',{x:10,y:20},'ABC'],['middle',{x:100,y:50,'text-anchor':'middle'},'ABC'],['end',{x:100,y:50,'text-anchor':'end'},'ABC'],['spacing',{'font-family':'Arial','font-size':16,'letter-spacing':2,'word-spacing':3},'A B'],['dxdy',{x:10,y:20,dx:5,dy:-3},'ABC'],['xlist',{x:'10 40 80',y:20},'ABC'],['deltas',{x:10,y:20,dx:'1 2 3',dy:'4 5 6'},'ABC'],['preserve',{'xml:space':'preserve'},' A  B '],['cyrillic',{'font-family':'Arial'},'Привет'],['kerningOff',{'font-family':'Arial','font-kerning':'none'},'AVAV'],['baselineMiddle',{x:10,y:20,'dominant-baseline':'middle'},'ABC'],['baselineHanging',{x:10,y:20,'dominant-baseline':'hanging'},'ABC']])run(name,()=>{const n=make('text',attrs,text);svg.appendChild(n);const b=box(n);n.remove();return b});
 run('span',()=>{const n=make('text',{x:10,y:30},'A'),span=make('tspan',{},'BC');n.appendChild(span);svg.appendChild(n);return {parent:box(n),span:box(span)}});
 run('spanPosition',()=>{const n=make('text',{x:10,y:30},'A'),span=make('tspan',{x:100,dy:20,'font-size':32},'BC');n.appendChild(span);svg.appendChild(n);return {parent:box(n),span:box(span)}});
 run('group',()=>{const g=make('g',{'font-family':'Arial','font-size':20}),n=make('text',{x:10,y:30},'ABC');g.appendChild(n);svg.appendChild(g);return [box(n),box(g)]});
 run('mutation',()=>{const n=make('text',{},'AAAA');svg.appendChild(n);const a=box(n);n.textContent='AAAB';const b=box(n);n.textContent='AAAA';return [a,b,box(n)]});
 svg.remove();return out;
})()
